const course = { name: '리액트 입문', seats: 3 };

function enroll(count) {
  if (count < 1) {
    throw new Error('신청 인원은 1명 이상이어야 합니다');
  }
  if (count > course.seats) {
    throw new Error('남은 자리는 ' + course.seats + '자리입니다');
  }
  return course.name + ' ' + count + '명 신청 완료';
}

const lines = [];

for (const count of [2, 5, 0]) {
  try {
    lines.push(enroll(count));
  } catch (e) {
    lines.push('신청 실패 · ' + e.message);
  }
}

console.log(lines.join('\n'));

